"""Printed 245–248: given elements and full source tangent derivations."""
from math12_reviewed_unit1 import heading,paragraph,page
from math12_reviewed_higher_derivatives import eq,note
from math12_native_geometry import geometry,path

def graph(n):
 if n==6:
  p=-2;vertical=True;scale=30;origin=(235,115);samples=[i/20 for i in range(-80,81)];coords=[(t,t*t/(4*p)) for t in samples];focus=(0,p);directrix=-p;extra=[];label='x²=−8y'
 elif n==7:
  p=5/8;vertical=False;scale=65;origin=(130,175);samples=[i/40 for i in range(-75,76)];coords=[(t*t/(4*p),t) for t in samples];focus=(p,0);directrix=-p;extra=[(p,2*p),(p,-2*p)];label='y²=(5/2)x'
 else:
  p=-.5;vertical=False;scale=52;origin=(345,175);samples=[i/40 for i in range(-90,91)];coords=[(t*t/(4*p),t) for t in samples];focus=(p,0);directrix=-p;extra=[(-2,2),(-2,-2)];label='y²=−2x'
 def pt(x,y):return(origin[0]+scale*x,origin[1]-scale*y)
 paths=[path([pt(x,y) for x,y in coords]),path([(45,origin[1]),(465,origin[1])]),path([(origin[0],30),(origin[0],315)])]
 paths.append(path([pt(-5,directrix),pt(5,directrix)] if vertical else [pt(directrix,-2.5),pt(directrix,2.5)],dash=True))
 if n==7:paths.append(path([pt(*extra[0]),pt(*extra[1])]))
 labels=[(origin[0]-16,origin[1]+22,'V(0,0)'),(470,origin[1]+6,'x'),(origin[0]-3,24,'y'),(50,45,label)]
 fx,fy=pt(*focus);labels.append((fx+6,fy+22,'F(0,−2)' if n==6 else 'F(5/8,0)' if n==7 else 'F(−1/2,0)'))
 dx,dy=pt(-3,directrix) if vertical else pt(directrix,2.2);labels.append((dx+6,dy-7,'y=2' if n==6 else 'x=−5/8' if n==7 else 'x=1/2'))
 for x,y in extra:
  a,b=pt(x,y);labels.append((a+6,b-7,f'({x:g},{y:g})'))
 if n==7:labels.append((245,65,'Half latus rectum: 2p=5/4'))
 return geometry('Figure 9.'+str(n),'Figure 9.'+str(n)+' — exact given-element parabola with focus, directrix and source coordinate points',paths,labels,points=[{'x':pt(x,y)[0],'y':pt(x,y)[1]} for x,y in [(0,0),focus]+extra],size=(520,350))

PAGES=[page('127_page_1.jpg',245,[graph(6),graph(7),paragraph('b. By inspection, the value of p is p = 5/8 that satisfies the directrix x = −5/8. This gives the equation of parabola y² = 4px = 4(5/8)x = (5/2)x, that opens right (p > 0) and the line of symmetry is the positive x-axis. This is shown in Figure 9.7.'),paragraph('c. By inspection, the value of p is p = −1/2 that satisfies the directrix x = 1/2. This gives the equation of parabola y² = 4px = 4(−1/2)x = −2x, that opens left (p < 0) and the line of symmetry is the negative x-axis. This is shown in Figure 9.8.'),graph(8),heading('(v) Recognition of tangent and normal to a parabola'),paragraph('A line which is parallel to the axis of a parabola intersects the parabola in only one (finite) point; all other lines will cut the parabola in two real and distinct points, real and coincident points, or complex conjugate points. “A line which meets a parabola in two coincident points is called a tangent”. A tangent to any curve at a point P is the limiting position of a secant line, cutting the curve in two points P and Q as Q → P. The normal can easily be shown in the subsection of this section.'),heading('(vi) The condition at which a line is tangent to parabola at a point'),paragraph('The line is tangent to a parabola, when the line intersects it in two real and coincident points. The given parabola and line:'),eq(r'y^2=4px','8'),eq(r'y=mx+c','9'),paragraph('develops a system of nonlinear equations:'),eq(r'y^2=4px,quad y=mx+c','10'),paragraph('The solution set (x,y) of the system of nonlinear equations (10) exists only, if the curves of the system (10) are intersecting. The set of points of intersection (x,y), a solution set can be found by solving the nonlinear system (10) simultaneously.'),note('Each axis-parallel line meets a nondegenerate parabola in one finite point, but this does not make it tangent. A vertical line x=k through y²=4px is not axis-parallel and needs separate treatment: it has two, one or zero real intersections according to pk>0, =0 or <0. Its vertex tangent is x=0. Complex solutions are algebraic intersections, not visible points of the real graph. Axes of symmetry are whole lines, while the sign of p gives the opening direction.')]),
page('127_page_2.jpg',246,[paragraph('The line (9) is used in parabola (8) to obtain the quadratic equation in x:'),eq(r'(mx+c)^2=4px'),eq(r'm^2x^2+2mcx+c^2=4px'),eq(r'm^2x^2+2x(mc-2p)+c^2=0','11'),paragraph('The equation (11) being a quadratic equation in x, gives a set of two values x₁ and x₂ which will be used in line (9) to obtain a set of two values y₁ and y₂. Thus a solution set {(x₁,y₁),(x₂,y₂)} of system (10) is a set of points of intersection. The points of intersection are real, coincident or imaginary according as the roots are real, coincident or imaginary or the discriminant of equation (11):'),eq(r'\mathrm{Disc}=4(mc-2p)^2-4m^2c^2>0\quad\mathrm{real\ and\ different}'),eq(r'\mathrm{Disc}=4(mc-2p)^2-4m^2c^2=0\quad\mathrm{real\ and\ coincident}'),eq(r'\mathrm{Disc}=4(mc-2p)^2-4m^2c^2<0\quad\mathrm{imaginary}'),heading('Example 4'),paragraph('For what condition the tangent line 4x−y−4 = 0 intersects the parabola x² = y?'),heading('Solution'),eq(r'4x-y-4=0\quad\Rightarrow\quad y=4x-4','12'),eq(r'x^2=y','13'),paragraph('Use line (12) in parabola (13) to obtain the x-coordinates of the points of intersection:'),eq(r'x^2=4x-4\quad\Rightarrow\quad x^2-4x+4=0\quad\Rightarrow\quad(x-2)^2=0\quad\Rightarrow\quad x=2,2'),paragraph('The x-coordinates are used in line (12) to obtain y=4,4. Thus the set of points of intersection (2,4) and (2,4) are real and coincident and the tangent line 4x−y−4 = 0 intersects parabola (13) at two coincident points (2,4) and (2,4).'),heading('a. The Equation of a tangent line in slope-form'),paragraph('If m is the slope of the tangent to parabola:'),eq(r'y^2=4px','14'),paragraph('then the equation of the tangent is of the form:'),eq(r'y=mx+c','15'),paragraph('Use line (15) in parabola (14) to obtain the quadratic equation in x:'),eq(r'(mx+c)^2=4px'),eq(r'm^2x^2+c^2+2mcx=4px'),eq(r'm^2x^2+2(mc-2p)x+c^2=0','16'),paragraph('If line (15) touches parabola (14), then equation (16) has coincident roots for which its discriminant equals zero:'),eq(r'4(mc-2p)^2-4(m^2)(c^2)=0'),eq(r'4m^2c^2+16p^2-16mcp-4m^2c^2=0'),eq(r'16p^2-16mcp=0'),note('The quadratic discriminant argument in x requires m≠0. When m=0, y=c instead gives the single intersection x=c²/(4p) and is not tangent for p≠0. For Example 4 there is one geometric contact (2,4), a root of multiplicity two; differentiation gives slope 2x=4 there, checking the given line.')]),
page('128_page_1.jpg',247,[eq(r'16p(p-mc)=0\quad\Rightarrow\quad p-mc=0\quad\Rightarrow\quad c=\frac p m','17'),paragraph('Equation (17) represents the condition of tangency. Use its value of c in line (15) to obtain the required equation of tangent:'),eq(r'y=mx+\frac p m','18'),heading('Remember'),paragraph('The equation of any tangent to parabola y²=4px in slope form is y=mx+p/m. The line y=mx+c should touch the parabola y²=4px under condition:'),eq(r'y=mx+c=mx+\frac p m,\quad c=\frac p m,\quad y^2=4px','19'),paragraph('The condition of tangency in case of parabola x²=4py and line y=mx+c is:'),eq(r'y=mx+c=mx-pm^2,\quad c=-pm^2,\quad x^2=4py','20'),heading('Example 5'),paragraph('For what value of c, the line x−y+c = 0 will touch the parabola x² = 8y? Use that value of c to find the tangent line that should touch the given parabola.'),heading('Solution'),paragraph('The value of c at which the line x−y+c = 0 will touch the given parabola through result (20) is:'),eq(r'c=-pm^2=-2(1)=-2'),eq(r'x^2=4py=4(2)y,\quad p=2,\quad m=1'),paragraph('Here m=1 is the slope of line x−y+c=0. The required tangent through (20) is:'),eq(r'y=mx+c=x-2\quad\Rightarrow\quad x-y-2=0'),heading('(vii) The Equation of a tangent and a normal to a parabola at a point'),heading('a. Equation of a tangent to a parabola at a point'),paragraph('Let the equation of the tangent line at a point p(x₁,y₁) to parabola y²=4px be:'),eq(r'y-y_1=m_1(x-x_1)','21'),paragraph('The slope m₁ at p(x₁,y₁) can be found by differentiating y²=4px with respect to x:'),eq(r'2y\frac{dy}{dx}=4p\quad\Rightarrow\quad\frac{dy}{dx}=\frac{2p}{y}\quad\Rightarrow\quad\left(\frac{dy}{dx}\right)_{(x_1,y_1)}=\frac{2p}{y_1}=m_1','22'),paragraph('Substitution of (22) in (21) gives the tangent line:'),eq(r'y-y_1=m_1(x-x_1)'),eq(r'y-y_1=\frac{2p}{y_1}(x-x_1)'),note('For y²=4px, assume p≠0 and m≠0 in the slope form; x=0 is the missing vertical vertex tangent. For x²=4py, finite slopes m include m=0, yielding the vertex tangent y=0. The derivation dividing by y₁ excludes y₁=0; the final point form on the next page remains valid there. The vertical-form condition follows by substituting y=mx+c into x²=4py: discriminant 16p²m²+16pc=0 gives c=−pm².')]),
page('128_page_2.jpg',248,[eq(r'yy_1-y_1^2=2px-2px_1'),eq(r'yy_1-4px_1=2px-2px_1,\quad y_1^2=4px_1'),eq(r'yy_1=2px+2px_1\quad\Rightarrow\quad yy_1=2p(x+x_1)','23'),heading('Note'),paragraph('The equation of the tangent line at a point p(x₁,y₁) to parabola x²=4py is:'),eq(r'xx_1=2p(y+y_1)','24'),paragraph('If the tangent line y=mx+p/m to parabola y²=4px is identical to yy₁=2p(x+x₁), then compare coefficients of like terms to obtain the contact point:'),eq(r'mx=\frac{2px}{y_1}\quad\Rightarrow\quad y_1=\frac{2p}{m}'),eq(r'\frac{2px_1}{y_1}=\frac p m\quad\Rightarrow\quad 2x_1=\frac{y_1}{m}\quad\Rightarrow\quad 2x_1=\frac{2p}{m^2}\quad\Rightarrow\quad x_1=\frac p{m^2}'),eq(r'P(x_1,y_1)=\left(\frac p{m^2},\frac{2p}{m}\right),\quad y^2=4px','25'),paragraph('If the tangent line y=mx−pm² to parabola x²=4py is identical to xx₁=2p(y+y₁), compare coefficients of like terms to obtain the point of contact:'),eq(r'mx=\frac{xx_1}{2p}\quad\Rightarrow\quad x_1=2pm'),eq(r'-pm^2=-y_1\quad\Rightarrow\quad y_1=pm^2'),eq(r'P(x_1,y_1)=(2pm,pm^2),\quad x^2=4py','26'),heading('Example 6'),paragraph('Find the equation of tangent line at a point p(2,−4) to parabola y²=8x. Show that p(2,−4) is the point of contact between the required tangent line and the given parabola.'),heading('Solution'),paragraph('Result (23) is used to obtain the tangent line:'),eq(r'yy_1=2p(x+x_1)'),eq(r'y(-4)=2(2)(x+2),\quad P(x_1,y_1)=(2,-4),\quad 4p=8'),eq(r'-4y=4x+8\quad\Rightarrow\quad4x+4y+8=0\quad\Rightarrow\quad x+y+2=0'),paragraph('The point of contact through result (25) is:'),eq(r'P(x_1,y_1)=\left(\frac p{m^2},\frac{2p}{m}\right)=(2,-4),\quad p=2,\quad m=-1'),heading('b. The Equation of a normal line to a parabola at a point'),paragraph('The equation of the normal line at a point p(x₁,y₁) to parabola y²=4px is:'),eq(r'y-y_1=m_2(x-x_1)','27'),note('The point forms assume the stated contact lies on its parabola. They include the vertices: y₁=x₁=0 yields x=0 for y²=4px and y=0 for x²=4py when p≠0. The contact formula (25) requires finite nonzero m; formula (26) permits any finite m. The letter p denotes the signed focal parameter while P denotes the contact point. The normal derivation continues on printed page 249.')])]
